import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

import '../models/models.dart';
import '../services/claude_service.dart';
import '../services/database.dart';
import '../services/pdf_exporter.dart';
import '../services/settings.dart';
import 'settings_screen.dart';

/// ADHD mode: short key-point cards for each chapter, generated by Claude,
/// and a one-tap PDF export.
class AdhdScreen extends StatefulWidget {
  final Book book;
  final List<Chapter> chapters;
  const AdhdScreen({super.key, required this.book, required this.chapters});

  @override
  State<AdhdScreen> createState() => _AdhdScreenState();
}

class _AdhdScreenState extends State<AdhdScreen> {
  final _db = AppDatabase.instance;
  Map<int, ChapterInsight> _insights = {};
  final Set<int> _working = {};
  bool _batchRunning = false;
  bool _cancelBatch = false;
  bool _exporting = false;

  @override
  void initState() {
    super.initState();
    _db.insights(widget.book.id!).then((v) {
      if (mounted) setState(() => _insights = v);
    });
  }

  ClaudeService? _service() {
    final s = context.read<AppSettings>();
    if (!s.hasApiKey) {
      showDialog(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Text('需要 Claude API 金鑰'),
          content: const Text('AI 重點需要你自己的 Claude API 金鑰，請先到設定頁貼上。'),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('稍後')),
            FilledButton(
              onPressed: () {
                Navigator.pop(ctx);
                Navigator.push(
                    context, MaterialPageRoute(builder: (_) => const SettingsScreen()));
              },
              child: const Text('前往設定'),
            ),
          ],
        ),
      );
      return null;
    }
    return ClaudeService(s.apiKey);
  }

  Future<bool> _analyze(ClaudeService service, Chapter ch) async {
    setState(() => _working.add(ch.index));
    try {
      final ins = await service.analyzeChapter(
          bookId: widget.book.id!, bookTitle: widget.book.title, chapter: ch);
      await _db.saveInsight(ins);
      if (mounted) setState(() => _insights[ch.index] = ins);
      return true;
    } on ClaudeException catch (e) {
      _snack('${ch.title}：${e.message}');
      return false;
    } finally {
      if (mounted) setState(() => _working.remove(ch.index));
    }
  }

  Future<void> _analyzeAll() async {
    final service = _service();
    if (service == null) return;
    setState(() {
      _batchRunning = true;
      _cancelBatch = false;
    });
    for (final ch in widget.chapters) {
      if (_cancelBatch || !mounted) break;
      if (_insights.containsKey(ch.index)) continue;
      final ok = await _analyze(service, ch);
      if (!ok) break; // stop on first error (bad key, rate limit…)
    }
    if (mounted) setState(() => _batchRunning = false);
  }

  Future<void> _export() async {
    if (_insights.isEmpty) {
      _snack('還沒有任何重點，請先產生重點');
      return;
    }
    setState(() => _exporting = true);
    try {
      final notes = await _db.notes(widget.book.id!);
      final bytes = await PdfExporter.build(
        book: widget.book,
        chapters: widget.chapters,
        insights: _insights,
        notes: notes,
      );
      await PdfExporter.share(bytes, widget.book.title);
    } catch (e) {
      _snack('PDF 匯出失敗（第一次匯出需要網路下載中文字型）：$e');
    } finally {
      if (mounted) setState(() => _exporting = false);
    }
  }

  void _snack(String msg) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(msg)));
  }

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    final done = _insights.length;
    final total = widget.chapters.length;
    return Scaffold(
      appBar: AppBar(
        title: const Text('ADHD 重點模式'),
        actions: [
          IconButton(
            tooltip: '匯出 PDF',
            onPressed: _exporting ? null : _export,
            icon: _exporting
                ? const SizedBox(
                    width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2))
                : const Icon(Icons.picture_as_pdf_outlined),
          ),
        ],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 8, 16, 8),
            child: Row(
              children: [
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text('已整理 $done / $total 章'),
                      const SizedBox(height: 4),
                      LinearProgressIndicator(value: total == 0 ? 0 : done / total),
                    ],
                  ),
                ),
                const SizedBox(width: 12),
                _batchRunning
                    ? OutlinedButton.icon(
                        onPressed: () => setState(() => _cancelBatch = true),
                        icon: const Icon(Icons.stop),
                        label: const Text('停止'),
                      )
                    : FilledButton.icon(
                        onPressed: done == total ? null : _analyzeAll,
                        icon: const Icon(Icons.auto_awesome),
                        label: Text(done == 0 ? '整理全書' : '整理其餘章節'),
                      ),
              ],
            ),
          ),
          const Divider(height: 1),
          Expanded(
            child: ListView.builder(
              padding: const EdgeInsets.fromLTRB(12, 12, 12, 96),
              itemCount: widget.chapters.length,
              itemBuilder: (ctx, i) {
                final ch = widget.chapters[i];
                final ins = _insights[i];
                final working = _working.contains(i);
                return Card(
                  child: Padding(
                    padding: const EdgeInsets.all(14),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          children: [
                            Expanded(
                              child: Text(ch.title,
                                  style: Theme.of(context).textTheme.titleMedium),
                            ),
                            if (working)
                              const SizedBox(
                                  width: 20,
                                  height: 20,
                                  child: CircularProgressIndicator(strokeWidth: 2))
                            else
                              IconButton(
                                tooltip: ins == null ? '產生重點' : '重新產生',
                                icon: Icon(ins == null ? Icons.auto_awesome : Icons.refresh),
                                onPressed: _batchRunning
                                    ? null
                                    : () {
                                        final s = _service();
                                        if (s != null) _analyze(s, ch);
                                      },
                              ),
                          ],
                        ),
                        if (ins == null && !working)
                          Text('尚未整理', style: TextStyle(color: scheme.outline)),
                        if (ins != null) ...[
                          if (ins.oneLine.isNotEmpty)
                            Container(
                              width: double.infinity,
                              margin: const EdgeInsets.only(top: 4, bottom: 8),
                              padding: const EdgeInsets.all(10),
                              decoration: BoxDecoration(
                                color: scheme.primaryContainer,
                                borderRadius: BorderRadius.circular(8),
                              ),
                              child: Text(ins.oneLine,
                                  style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                      color: scheme.onPrimaryContainer)),
                            ),
                          for (var k = 0; k < ins.keyPoints.length; k++)
                            Padding(
                              padding: const EdgeInsets.only(bottom: 6),
                              child: Row(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  CircleAvatar(
                                    radius: 11,
                                    backgroundColor: scheme.primary,
                                    child: Text('${k + 1}',
                                        style: TextStyle(
                                            fontSize: 12, color: scheme.onPrimary)),
                                  ),
                                  const SizedBox(width: 8),
                                  Expanded(child: Text(ins.keyPoints[k])),
                                ],
                              ),
                            ),
                          if (ins.keywords.isNotEmpty)
                            Wrap(
                              spacing: 6,
                              runSpacing: 6,
                              children: ins.keywords
                                  .map((k) => Chip(
                                        label: Text(k),
                                        visualDensity: VisualDensity.compact,
                                      ))
                                  .toList(),
                            ),
                        ],
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
        ],
      ),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _exporting ? null : _export,
        icon: const Icon(Icons.picture_as_pdf),
        label: const Text('匯出 PDF'),
      ),
    );
  }
}
